using System;
using System.IO;
using System.Linq;
using IdleIntelligence.Core;
using NUnit.Framework;
using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class GemQuoteSnapshot{public string id,reason;public long cost;public bool enabled,owned,hasTime;public double remaining,applied;}
 [Serializable]public sealed class CapsuleQuoteSnapshot{public string reason;public long next;public bool allowed,videoAllowed;public int videoRemaining;}
 [Serializable]public sealed class GemFeatureStep{public string action,id,random,result;public double at,componentsEarned,trainingCompleted,regularCredits,regularData,offline;public int amount,draws,quality,efficiency,integration,labCount;public bool error,hasTraining,hasModuleJob,hasResearchJob;public UpgradeState upgrades;public CapsuleState capsules;public RetentionState retention;public long[] components,modules;public long modelLevel,nextId;public Job training,moduleJob,researchJob;public Job[] labs;public TrainingTarget[] trainingQueue;public int[] research;public ItemInstance[] inventory;public NumberData credits,data,eligible;public GemQuoteSnapshot[] quotes;public CapsuleQuoteSnapshot capsuleQuote;}
 [Serializable]public sealed class GemFeatureScenario{public string name;public StateData before;public GemFeatureStep[] steps;}
 [Serializable]public sealed class GemFeatureCases{public int transactions;public GemFeatureScenario[] scenarios;}
 public sealed class GemFeatureTests
 {
  static void Near(ScientificNumber actual,NumberData expected,string label){var e=ScientificNumber.FromData(expected);if(e.IsZero)Assert.That(actual.IsZero,Is.True,label);else Assert.That(actual.Log10(),Is.EqualTo(e.Log10()).Within(2e-10),label);}
  static void JobEqual(Job actual,Job expected,string label){Assert.That(actual==null,Is.EqualTo(expected==null),label+" presence");if(actual==null)return;Assert.That(actual.id,Is.EqualTo(expected.id),label+" ID");Assert.That(actual.required,Is.EqualTo(expected.required).Within(Math.Max(1e-7,Math.Abs(expected.required)*1e-12)),label+" required");Assert.That(actual.done,Is.EqualTo(expected.done).Within(Math.Max(1e-7,Math.Abs(expected.done)*1e-12)),label+" paid/applied work");}
  [Test]public void AllGemOffersEffectsAndCapsuleOutcomesMatchActualTypeScript()
  {
   var f=JsonUtility.FromJson<GemFeatureCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/GemFeatureReferenceCases.json")));Assert.That(f.transactions,Is.GreaterThan(300));int count=0;
   foreach(var scenario in f.scenarios){var s=scenario.before.ToState();foreach(var c in scenario.steps){string label=scenario.name+" / "+count++ +" "+c.action+" "+c.id,original=JsonUtility.ToJson(StateData.From(s));int draws=0;Func<double> rng=c.random=="seeded"?null:(Func<double>)(()=>{draws++;if(c.random=="throws")throw new InvalidOperationException("injected");return c.random=="nan"?double.NaN:double.Parse(c.random,System.Globalization.CultureInfo.InvariantCulture);});var n=s;bool error=false;try{switch(c.action){case "gem":n=GemShop.Buy(s,c.id,c.at);break;case "capsule":n=Capsules.Draw(s,long.Parse(c.id),rng);break;case "video":n=Capsules.RewardVideo(s,c.id,c.result,c.at,rng);break;case "train":n=Game.Train(s,c.id);break;case "queue":n=PrestigeAutomation.QueueTraining(s,c.id);break;case "research":n=Game.Research(s,c.id);break;case "module":n=Workshop.StartModule(s,Array.FindIndex(ItemBalance.Modules,m=>m.Id==c.id));break;case "advance":n=Game.Advance(s,c.at);break;case "start":n=ChallengeRules.Start(s,"no-taps",1,"gem-source");break;case "serial":n=ChallengeRules.Start(s,"serial-science",1,"gem-source");break;case "abort":n=ChallengeRules.Return(s,false);break;case "reset":n=PrestigeRules.Reset(s);break;}}catch{error=true;n=s;}
    Assert.That(error,Is.EqualTo(c.error),label+" error contract");Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),label+" pure");if(c.action=="capsule"||c.action=="video")Assert.That(draws,Is.EqualTo(c.draws),label+" RNG sequence");Assert.That(JsonUtility.ToJson(n.Upgrades),Is.EqualTo(JsonUtility.ToJson(c.upgrades)),label+" permanent/boost/purchase state");var actualCapsule=n.Capsules.Copy();var expectedCapsule=c.capsules.Copy();if(actualCapsule.hasLast&&actualCapsule.last.hasResource&&expectedCapsule.hasLast&&expectedCapsule.last.hasResource){Near(ScientificNumber.FromData(actualCapsule.last.amount),expectedCapsule.last.amount,label+" capsule receipt resource");actualCapsule.last.amount=null;expectedCapsule.last.amount=null;}Assert.That(JsonUtility.ToJson(actualCapsule),Is.EqualTo(JsonUtility.ToJson(expectedCapsule)),label+" capsule receipt/limits/dedup");Assert.That(JsonUtility.ToJson(n.Retention),Is.EqualTo(JsonUtility.ToJson(c.retention)),label+" wallet/ledger");Assert.That(n.Workshop.components,Is.EqualTo(c.components),label+" materials");Assert.That(n.Workshop.modules,Is.EqualTo(c.modules),label+" actual module completion");Assert.That(n.Workshop.nextId,Is.EqualTo(c.nextId),label+" IDs");Assert.That(n.ModelLevel,Is.EqualTo(c.modelLevel),label+" actual model level");Assert.That(new[]{n.Quality,n.Efficiency,n.Workshop.integration},Is.EqualTo(new[]{c.quality,c.efficiency,c.integration}),label+" training tracks");Assert.That(n.Research,Is.EqualTo(c.research),label+" actual research completion");JobEqual(n.Training,c.hasTraining?c.training:null,label+" training");JobEqual(n.Workshop.hasModuleJob?n.Workshop.moduleJob:null,c.hasModuleJob?c.moduleJob:null,label+" module");JobEqual(n.ResearchJob,c.hasResearchJob?c.researchJob:null,label+" first lab");Assert.That(n.Prestige.labs.Length,Is.EqualTo(c.labs.Length),label+" parallel labs");for(int i=0;i<c.labs.Length;i++)JobEqual(n.Prestige.labs[i],c.labs[i],label+" lab "+i);Assert.That(n.Prestige.trainingQueue.Select(j=>j.track+":"+j.level),Is.EqualTo(c.trainingQueue.Select(j=>j.track+":"+j.level)),label+" next queued training");Assert.That(JsonUtility.ToJson(new SeasonTests.ItemList{items=n.Workshop.inventory}),Is.EqualTo(JsonUtility.ToJson(new SeasonTests.ItemList{items=c.inventory})),label+" item result");Assert.That(n.Lifetime.componentsEarned,Is.EqualTo(c.componentsEarned).Within(1e-6),label+" components producer");Assert.That(n.Lifetime.trainingCompleted,Is.EqualTo(c.trainingCompleted),label+" completion producer");Assert.That(n.Lifetime.regularCredits,Is.EqualTo(c.regularCredits).Within(Math.Max(1e-7,Math.Abs(c.regularCredits)*1e-12)),label+" capsule credits excluded from regular income");Assert.That(n.Lifetime.regularData,Is.EqualTo(c.regularData).Within(Math.Max(1e-7,Math.Abs(c.regularData)*1e-12)),label+" capsule data follows addDataScientific lifetime contract");Near(n.Credits,c.credits,label+" credits");Near(n.Data,c.data,label+" data");Near(n.Prestige.Eligible,c.eligible,label+" eligible income");Assert.That(PrestigeAutomation.LabCount(n),Is.EqualTo(c.labCount),label+" actual slot capacity");Assert.That(Game.OfflineLimit(n),Is.EqualTo(c.offline),label+" actual offline cap");foreach(var expected in c.quotes){var q=GemShop.Quote(n,expected.id);Assert.That(q.Cost,Is.EqualTo(expected.cost),label+" quote "+expected.id+" cost");Assert.That(q.Enabled,Is.EqualTo(expected.enabled),label+" quote "+expected.id+" enabled");Assert.That(q.Reason??"",Is.EqualTo(expected.reason),label+" quote "+expected.id+" reason");Assert.That(q.Owned,Is.EqualTo(expected.owned),label+" quote "+expected.id+" owned");Assert.That(q.HasTime,Is.EqualTo(expected.hasTime),label+" quote "+expected.id+" time");Assert.That(q.Remaining,Is.EqualTo(expected.remaining).Within(1e-6),label+" quote remaining");Assert.That(q.Applied,Is.EqualTo(expected.applied).Within(1e-6),label+" quote applied");}var cq=Capsules.Quote(n);Assert.That(cq.Reason??"",Is.EqualTo(c.capsuleQuote.reason),label+" capsule gate");Assert.That(cq.Next,Is.EqualTo(c.capsuleQuote.next),label+" capsule ID");Assert.That(cq.Allowed,Is.EqualTo(c.capsuleQuote.allowed),label+" capsule affordability");Assert.That(cq.VideoAllowed,Is.EqualTo(c.capsuleQuote.videoAllowed),label+" capsule video");Assert.That(cq.VideoRemaining,Is.EqualTo(c.capsuleQuote.videoRemaining),label+" capsule quota");Game.Validate(n);s=n;
   }}Assert.That(count,Is.EqualTo(f.transactions));
  }
 }
}
